import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as l,af as o}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const p=JSON.parse('{"title":"Loop 工程实践：从报警到自动修复（PolarDB-X 案例）","description":"把 Agent 从帮写代码推到接告警、自主分析、稳定复现、修复、提交评审。八张可执行卡：起点前移、现场信息产品化、诊断 Skills、运行时验证、内存现场、复现环境分级、稳定复现门禁、云端常驻。","frontmatter":{"title":"Loop 工程实践：从报警到自动修复（PolarDB-X 案例）","description":"把 Agent 从帮写代码推到接告警、自主分析、稳定复现、修复、提交评审。八张可执行卡：起点前移、现场信息产品化、诊断 Skills、运行时验证、内存现场、复现环境分级、稳定复现门禁、云端常驻。","domain":"practice","tags":["team","efficiency","loop","incident"],"outline":[2,3],"navOrder":30,"prev":{"text":"采购与实施方案","link":"/zh/practice/procurement-plan"},"next":false,"listed":true},"headers":[],"relativePath":"zh/practice/agent-handbook/case-loop-auto-repair.md","filePath":"zh/practice/agent-handbook/case-loop-auto-repair.md","lastUpdated":1792458633000}'),i={name:"zh/practice/agent-handbook/case-loop-auto-repair.md"};function r(n,a,d,h,s,c){return l(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="loop-工程实践-从报警到自动修复-polardb-x-案例" tabindex="-1">Loop 工程实践：从报警到自动修复（PolarDB-X 案例） <a class="header-anchor" href="#loop-工程实践-从报警到自动修复-polardb-x-案例" aria-label="Permalink to &quot;Loop 工程实践：从报警到自动修复（PolarDB-X 案例）&quot;">​</a></h1><blockquote><p>案例来源：阿里云《AI Agent Handbook》第 25 章《研发效能》——<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">从报警到自动修复，PolarDB-X 的 Loop 工程实践</a>。 本页只做转述与提炼，不整段搬运原文；每张卡的引文均逐字来自该章，可点链接复核。</p></blockquote><h2 id="这套做法回答什么问题" tabindex="-1">这套做法回答什么问题 <a class="header-anchor" href="#这套做法回答什么问题" aria-label="Permalink to &quot;这套做法回答什么问题&quot;">​</a></h2><p>值不值得把 Agent 从「帮写代码」推到「自己接报警」？原文给的答案不是「模型够不够强」，而是三件工程事：</p><ol><li>现场信息能不能让 Agent <strong>按需查询</strong>，而不是研发截几张图喂给它；</li><li>修复过程有没有「<strong>稳定复现</strong>」这个门禁，让评审时有可复查的证据；</li><li>Agent 能不能<strong>云端常驻</strong>，而不是每人本机各起一份。</li></ol><p>原文对价值的判断落在一句话上：提效范围要从编码环节扩展到完整缺陷处理过程。</p><blockquote><p>原文：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.4 节</a></p><p>「现场收集、根因排查、复现和测试验证由 Agent 自主完成后，研发可以围绕提交的证据和代码开展审查，无须再逐项承担前述工作。提效范围由编码环节扩展到完整的缺陷处理过程。」</p></blockquote><p>原文把任务分成两类，也决定了适用边界：需求明确的新功能开发仍由研发主导、Agent 执行；只有具备明确验证方法的任务才交给 Loop 自主推进。</p><blockquote><p>「对于这类任务，我们采用研发主导、Agent 执行的协作方式：研发负责方案和关键决策，并在开发、测试过程中持续把关；Agent 则承担具体的编码和测试工作。」</p></blockquote><blockquote><p>「其他团队可从具有明确验证方法的任务入手，接通所需信息和工具，完成从任务输入到结果交付的全流程，再根据实践逐步完善。」</p></blockquote><hr><h2 id="卡-1-把-agent-的任务起点前移到「收报警」" tabindex="-1">卡 1：把 Agent 的任务起点前移到「收报警」 <a class="header-anchor" href="#卡-1-把-agent-的任务起点前移到「收报警」" aria-label="Permalink to &quot;卡 1：把 Agent 的任务起点前移到「收报警」&quot;">​</a></h2><h3 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>原有流程里，研发既要编码测试，又要承担问题分析、根因定位和修复需求产出。一次修复最终可能只涉及几行代码，但排查吃掉了大部分时间——只让 Agent 帮写代码，省下的非常有限。</p><h3 id="具体做法" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ul><li><strong>换起点</strong>：从接收人工整理好的修复需求，改成直接接收报警或工单。</li><li><strong>Agent 自认现场</strong>：自主确认问题发生在哪个实例、涉及哪些节点、运行什么版本、异常前后发生了什么。</li><li><strong>强制迭代</strong>：要求它沿线索持续查询——发现节点异常后查同期日志，发现状态变化后查源码，而不是一次成稿。</li><li><strong>固定产物</strong>：这一阶段必须输出问题现象、时间线、相关证据、待验证的原因假设这四件套，作为后续复现的检查目标。</li><li><strong>保留人在环</strong>：结论仍提交研发审查，不是自动合并。</li></ul><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>报警/工单系统有可程序化入口（webhook 或 API），且能带出实例、节点、版本、时间窗。</li><li>至少有一条真实故障链路的完整日志、监控、拓扑可查（卡 2 展开）。</li><li>有一份「这个系统通常怎么排」的 SOP 可沉淀（卡 3 展开）。</li></ul><h3 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：现象具体、能靠复现验证假设的任务——线上告警、工单、回归出来的缺陷。</li><li>不适用：需求本身还在变的探索性开发（原文明确这类由研发主导、Agent 执行）。</li><li>不适用：只有截图、没有数据入口的外部投诉；跨团队协调类工单。</li></ul><h3 id="反例与失败模式" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>把排查结果截成监控截图交给 Agent：它无法自己扩时间窗，只能等研发补材料。</li><li>一次成稿：Agent 输出报告后不再自证，研发只能从零复核，等于没省事。</li><li>起点前移但没有数据入口：告警直接扔给 Agent，等于把噪声放大。</li></ul><h3 id="可验证的效果指标" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>首轮由 Agent 完成处理的告警占比（原文内部口径：半年内所有报警先由 Agent 完成首轮处理和分析）。</li><li>「等研发补材料」的回合数（目标趋近 0）。</li><li>Agent 产出的四件套完整率（现象/时间线/证据/假设缺一即不算完成）。</li></ul><h3 id="原文短引用" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.2 节 — 从人工整理需求到 Agent 自主分析</a></p><p>「这些表现促使我们将 Agent 的任务起点，从接收人工整理的修复需求，前移到直接接收报警或工单。」</p><p>「由 Agent 自主确认问题发生在哪个实例、涉及哪些节点、运行什么版本，以及异常前后发生了什么，将现场还原和问题分析一并纳入自主处理流程。」</p><p>「这一阶段应形成问题现象、时间线、相关证据和待验证的原因假设，为后续复现提供明确的检查目标。」</p></blockquote><hr><h2 id="卡-2-把现场信息产品化——集中日志-结构化-cli" tabindex="-1">卡 2：把现场信息产品化——集中日志 + 结构化 CLI <a class="header-anchor" href="#卡-2-把现场信息产品化——集中日志-结构化-cli" aria-label="Permalink to &quot;卡 2：把现场信息产品化——集中日志 + 结构化 CLI&quot;">​</a></h2><h3 id="要解决的问题-1" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-1" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>Agent 分析到一半发现还得看另一个节点、或者再往前一小时，如果只能找研发要，它就退化成聊天机器人；研发成了人肉 API 网关。</p><h3 id="具体做法-1" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-1" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><p>分三层，从便宜到贵：</p><ol><li><strong>集中</strong>：日志等数据集中管理。分散在各生产节点时，查询要逐节点访问、检索、汇总；集中后 Agent 用一个入口跨节点、跨时段取数。</li><li><strong>给现成 CLI/接口</strong>：常用平台提供结构化查询，返回 JSON 这类可解析结果（含节点、指标、采样点），让 Agent 按返回数据识别异常节点和时段，按需扩大范围。</li><li><strong>让 Agent 自己把存量平台包成 CLI</strong>：没有官方 CLI 的平台，参考已有 CLI 实现，让 Agent 操作浏览器走一遍功能、分析接口请求与认证方式，再把所需功能封装出来。</li></ol><h3 id="前置条件-1" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-1" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>平台愿意给只读权限与稳定的 API/CLI；返回值结构化（JSON）而非渲染后的页面。</li><li>有权限边界意识：Agent 用的是只读凭据，封装工具时不把高权限写进脚本。</li><li>有统一的工具落点（一个仓库/一个包目录），避免每个排查各自造轮子。</li></ul><h3 id="适用边界-1" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-1" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：任何需要按需跨节点、跨时段、跨指标关联分析的排查。</li><li>不适用：认证方式本身敏感、不愿让 Agent 持有的平台；数据量小到人工看一眼就够的场景。</li><li>提醒：线上多版本并存时，新版本修好的问题在老版本仍会出现，查询必须带版本维度。</li></ul><h3 id="反例与失败模式-1" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-1" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>只喂截图不喂接口：Agent 描述得了「看到了什么」，定位不到精确时间点。</li><li>没先集中日志就急着封 CLI：CLI 底层仍逐节点抓取，结果不可复现。</li><li>允许 Agent 自行封装高权限接口：省下的时间会以安全事故的形式还回去。</li></ul><h3 id="可验证的效果指标-1" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-1" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>常见查询走 CLI/API 的比例（目标：排查里 0 次人工截图）。</li><li>Agent 单次分析内的自主查询轮数（轮数上升 = 信息可达性变好）。</li><li>「等待研发补充材料」回合数的下降曲线。</li></ul><h3 id="原文短引用-1" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-1" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.2 节 — 通过结构化接口支持按需查询、将存量平台封装为 CLI</a></p><p>「为便于这些工具查询和关联现场信息，日志等数据也需要集中管理。如果日志分散在各个生产节点上，查询仍需逐节点访问、检索文件并汇总结果；集中到统一平台后，Agent 就能通过统一入口获取不同节点、不同时间段的数据。」</p><p>「我们进一步让 Agent 完成这项工作：参考已有 CLI 实现，自主操作浏览器、使用目标平台功能，分析接口请求和认证方式，再编写代码，将所需功能封装出来。」</p></blockquote><hr><h2 id="卡-3-把诊断方法沉淀成-skills" tabindex="-1">卡 3：把诊断方法沉淀成 Skills <a class="header-anchor" href="#卡-3-把诊断方法沉淀成-skills" aria-label="Permalink to &quot;卡 3：把诊断方法沉淀成 Skills&quot;">​</a></h2><h3 id="要解决的问题-2" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-2" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>排查套路只在老员工脑子里，Agent 每单都从零发明；工具用法散落在 wiki 和群里，Agent 检索不到，等于没有。</p><h3 id="具体做法-2" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-2" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ul><li>把<strong>诊断方法、CLI 工具说明、排查经验</strong>整理成 Skills（不是给人读的 FAQ，而是给 Agent 按需调用的程序性知识）。</li><li>一个诊断 Skill 的最小骨架：现象确认 → 查拓扑与基础指标 → 定位异常时段与组件 → 按原因假设选择验证手段（日志、火焰图等）→ 据结果调整方向。</li><li>配套资源与 Skill 同处：采集脚本、指标字典、日志查询模板、常见问题诊断参考，随取随用。</li></ul><h3 id="前置条件-2" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-2" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>已有若干「按这个套路能定位」的真实案例可提炼。</li><li>写 Skill 的视角切换：从给人解释原理，改成给 Agent 一步步可执行的判断与动作。</li><li>与平台 Skills 机制对齐（本站已有 <a href="https://ai.zenheart.site/zh/tech/06-agent-systems/skills" target="_blank" rel="noreferrer">Agent Skills</a> 页面可参考写法）。</li></ul><h3 id="适用边界-2" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-2" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：有稳定套路、可脚本化的诊断流程（数据库、交易链路、CI 流水线、服务性能）。</li><li>不适用：产品决策、业务策略这类没有对错判据的判断。</li></ul><h3 id="反例与失败模式-2" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-2" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>Skill 写成散文：Agent 读不到下一步该做什么，退化成背景知识。</li><li>脚本和文档分仓放：Agent 按文档找不到脚本，或按脚本不知道前提。</li><li>只写不更新：旧套路留在 Skill 里，Agent 按废弃路径排查。</li></ul><h3 id="可验证的效果指标-2" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-2" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>单次排查中 Skill 被调用与命中的次数（命中 = 真的省掉一轮试错）。</li><li>新成员/新 Agent 从上线到独立定位第一个根因的时长。</li><li>「同一类问题重复摸索」的复现率（应随时间下降）。</li></ul><h3 id="原文短引用-2" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-2" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.2 节末段</a></p><p>「此外，我们还将诊断方法、CLI 工具说明和排查经验整理为 Skills。」</p><p>「该 Skill 还配套提供采集脚本、指标字典、日志查询模板和常见问题诊断参考，供 Agent 按需查阅和调用。」</p></blockquote><hr><h2 id="卡-4-给-agent-运行时验证能力-保活调试会话-指定线程断点" tabindex="-1">卡 4：给 Agent 运行时验证能力（保活调试会话 + 指定线程断点） <a class="header-anchor" href="#卡-4-给-agent-运行时验证能力-保活调试会话-指定线程断点" aria-label="Permalink to &quot;卡 4：给 Agent 运行时验证能力（保活调试会话 + 指定线程断点）&quot;">​</a></h2><h3 id="要解决的问题-3" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-3" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>只读代码出根因报告，会把「可能发生的路径」当成「实际执行的路径」。原文的 MDL 案例里，Agent 给出的并发时序解释被人工验证推翻，之后多轮调整仍未收敛——静态推演解决不了执行顺序问题。</p><h3 id="具体做法-3" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-3" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ol><li><strong>会话型调试 CLI</strong>：交互式调试器对 Agent 太笨重（要维护进程、反复收发命令、跨调用保状态）。做法是后台进程持续保活调试会话，前台每次一条命令、随用随退，下一次调用接着操作同一现场。</li><li><strong>指定线程断点</strong>：只有目标线程触发断点，命中时只暂停该线程，其他线程继续跑；配合线程恢复操作，Agent 可以<strong>控制线程执行顺序</strong>验证特定时序。</li><li><strong>闭环写进流程</strong>：暂停 → 观察状态 → 对照源码分析 → 回到同一会话继续执行，让调试过程与分析过程衔接，而不是各跑一遍。</li></ol><h3 id="前置条件-3" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-3" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>你的语言有可编程的调试接口（JVM 的 JDI、Go 的 Delve/DAP、Node 的 inspector 协议、Python 的 debugpy 等），能被包成 CLI。</li><li>有权限在目标环境挂调试器（生产慎用，见卡 8 的隔离建议）。</li><li>有可复现的环境可以挂会话（见卡 6）。</li></ul><h3 id="适用边界-3" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-3" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：并发/时序类缺陷、状态机走错分支、偶发竞态、性能热点归因。</li><li>不适用：纯业务逻辑错误（读代码就能定位，不必上运行时）。</li><li>前提提醒：挂调试器会改变时序，结论要在同等条件下对照修复前后。</li></ul><h3 id="反例与失败模式-3" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-3" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>把 Agent 的根因报告直接当结论：原文案例里这正是被人工推翻的那一步。</li><li>只复现一次就下结论：偶然未触发 ≠ 已修复（见卡 7 的对照要求）。</li><li>只在最新版上验证：线上仍跑老版本时，问题可能照旧。</li></ul><h3 id="可验证的效果指标-3" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-3" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>提出假设到被实测否掉的收敛轮数（越少越好，理想个位数）。</li><li>静态分析与运行结果不一致的假设占比（这是 Agent 自我校正能力的体检指标）。</li><li>从低概率偶发转成可稳定复现的问题条数。</li></ul><h3 id="原文短引用-3" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-3" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.3 节 — 通过 JDB CLI 调试运行中的 Java 程序</a></p><p>「为此，我们基于 Java 调试接口 JDI 重新实现了 JDB CLI，通过后台进程持续维护调试会话。前台每条命令执行后即可退出，下一次调用仍能继续操作同一个调试现场，查看线程、断点和变量。」</p><p>「另一个关键能力是指定线程断点：只有目标线程会触发断点，命中时也只暂停该线程，其他线程继续运行。配合线程恢复操作，Agent 可以控制相关线程的执行顺序，验证特定时序下的程序行为。」</p><p>「偏差来自静态推演与实际执行的差异。」</p></blockquote><hr><h2 id="卡-5-把内存现场集中化-heap-dump-查询接口" tabindex="-1">卡 5：把内存现场集中化（Heap Dump + 查询接口） <a class="header-anchor" href="#卡-5-把内存现场集中化-heap-dump-查询接口" aria-label="Permalink to &quot;卡 5：把内存现场集中化（Heap Dump + 查询接口）&quot;">​</a></h2><h3 id="要解决的问题-4" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-4" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>排查对象泄漏、锁未释放这类问题时，光看代码不够，得看<strong>故障那一刻的内存状态</strong>：对象字段的值、引用关系。而 dump 文件动辄几十 GB，本地打开慢，逐项请人查又回到人肉环节。</p><h3 id="具体做法-4" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-4" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ul><li>把 Heap Dump 放在<strong>大内存机器上集中加载和处理</strong>，不让它在不同人之间传来传去。</li><li>给 Agent 提供<strong>查询接口</strong>：按需查对象字段和引用关系，拿到结果继续查相关对象，自主验证假设。</li><li>分析完把记录和最终报告上传到展示平台，供研发事后查阅与复核（原文内部数据：累计两千多份处理任务）。</li></ul><h3 id="前置条件-4" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-4" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>有一台内存吃得下 dump 的机器（云上大内存实例或托管的内存分析服务）。</li><li>一个能跑对象查询语言的服务端 + 简单查询接口（HTTP 即可）。</li><li>采集侧能安全触发 dump（常见做法是收到告警后由人采集，而非让 Agent 直接抓生产）。</li></ul><h3 id="适用边界-4" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-4" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：JVM 堆、Node 的 heap snapshot、Go 的 pprof profile、Rust 等能出进程级内存快照的运行时。</li><li>不适用：内存占用本就很小的服务；无法安全采集 dump 的强合规环境。</li></ul><h3 id="反例与失败模式-4" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-4" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>dump 落盘后在研发之间传：谁打开都要等，结论还不可复查。</li><li>让 Agent 直接读大文件：token 和上下文都撑不住。</li><li>没有归档与查询接口：分析记录随会话消失，下次同类问题重来一遍。</li></ul><h3 id="可验证的效果指标-4" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-4" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>从 dump 采集、Agent 取证到结论的总时长（目标：分钟级而非小时级）。</li><li>单份 dump 的查询次数与假设否掉率（越高说明 Agent 在真的用证据纠错）。</li><li>报告归档率（能否事后复查）。</li></ul><h3 id="原文短引用-4" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-4" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.3 节 — 通过 Heap Dump 查询内存现场</a></p><p>「Heap Dump 文件通常很大。我们将其放在大内存云服务器上集中加载和处理，并为 Agent 提供查询接口。」</p><p>「Agent 可以按需查询对象字段和引用关系，根据返回结果继续检查相关对象，自主验证分析假设，无须由研发逐项查询后再提供材料。」</p></blockquote><hr><h2 id="卡-6-按故障条件分级提供复现环境" tabindex="-1">卡 6：按故障条件分级提供复现环境 <a class="header-anchor" href="#卡-6-按故障条件分级提供复现环境" aria-label="Permalink to &quot;卡 6：按故障条件分级提供复现环境&quot;">​</a></h2><h3 id="要解决的问题-5" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-5" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>有了调试能力，还得有个能真跑起来的环境。万能环境既贵又难对齐版本与拓扑，简单问题用它是浪费。</p><h3 id="具体做法-5" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-5" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><p>原文按「故障条件」给两级，让 Agent 自行选择：</p><table tabindex="0"><thead><tr><th>环境</th><th>适用情况</th><th>使用方式</th></tr></thead><tbody><tr><td>临时实例</td><td>SQL 报错、功能异常等简单问题的初步复现</td><td>创建最新版本的临时实例，完成验证后释放</td></tr><tr><td>完整复现环境</td><td>依赖历史版本、特定拓扑，或需要控制并发时序的问题</td><td>按问题实例的版本和拓扑搭建，结合调试工具验证</td></tr></tbody></table><ul><li><strong>同一套环境兼任修复验证</strong>：改完代码把修复版部署到对应环境，按已确认的复现步骤重放一次，检验原始问题是否解决。</li><li><strong>复现失败也是数据</strong>：首次没触发故障时，让它据实际执行路径重排线程关系、断点与执行顺序再试，而不是宣布「无法复现」。</li></ul><h3 id="前置条件-5" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-5" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>有可编程创建的临时环境（容器、临时实例、CI 里的环境）。</li><li>有按版本/拓扑复刻的能力（版本号、节点数、分片规则等可参数化）。</li><li>资源回收机制：临时实例用完即释放，避免自建环境变成成本黑洞。</li></ul><h3 id="适用边界-5" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-5" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：能在测试环境重放的功能/时序缺陷。</li><li>不适用：依赖真实生产数据、硬件抖动、外部第三方时序的偶发问题——这类靠观测证据而非复现。</li><li>注意：线上多版本并存时，复现环境要按<strong>出问题那个版本</strong>建，否则等于没复现。</li></ul><h3 id="反例与失败模式-5" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-5" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>只在最新版本复现：改好了不代表老版本没问题（原文明确提到这个陷阱）。</li><li>复现不了就结案：低概率缺陷恰恰要求把偶然交错变成主动构造的步骤。</li><li>临时实例不回收：数量涨起来后没人敢删。</li></ul><h3 id="可验证的效果指标-5" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-5" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>首次复现成功率、平均复现尝试轮数。</li><li>临时环境的平均存活时长与回收率。</li><li>复现环境与线上版本、拓扑一致的比例（可抽查）。</li></ul><h3 id="原文短引用-5" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-5" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.3 节 — 根据故障条件选择复现环境、从低概率触发到稳定复现</a></p><p>「具备调试和内存分析工具后，还需要为 Agent 准备能够实际运行和复现问题的环境。我们提供了两类环境，Agent 可以根据问题情况自行选择。」</p><p>「这套环境也用于后续的修复验证。代码修改后，Agent 将修复后的版本部署到相应环境中，按照已经确认的复现步骤再次执行，检验原始问题是否得到解决。」</p><p>「经过几轮迭代，Agent 找到了之前遗漏的关键条件：要在连接进入语句执行状态之前发起 KILL，再控制后续关闭连接与获取 MDL 锁的执行顺序。」</p></blockquote><hr><h2 id="卡-7-把「稳定复现」设为修复交付门禁" tabindex="-1">卡 7：把「稳定复现」设为修复交付门禁 <a class="header-anchor" href="#卡-7-把「稳定复现」设为修复交付门禁" aria-label="Permalink to &quot;卡 7：把「稳定复现」设为修复交付门禁&quot;">​</a></h2><h3 id="要解决的问题-6" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-6" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>评审时凭什么相信「真修好了」——靠口头描述、靠在测试环境跑一下没复现，都不可复查。没有证据的合并，就是把风险推给线上。</p><h3 id="具体做法-6" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-6" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ol><li><strong>硬门禁</strong>：没有稳定复现用例，修复不进代码评审。</li><li><strong>把复现固化成用例</strong>：复现过程直接写成测试用例；并发类问题可在关键位置注入延迟，换取可重复执行。</li><li><strong>双向校验</strong>：该用例在<strong>修复前必须能触发原问题</strong>，<strong>修复后必须能正常通过</strong>，再叠加完整回归测试。</li><li><strong>不通过就回环</strong>：没通过就继续分析和修改，直到满足要求。</li><li><strong>评审顺序固定</strong>：研发先检查复现用例、对照原始问题确认它覆盖目标故障，再审查代码修改。</li><li><strong>提交物成套</strong>：代码修改 + 复现用例 + 修复前后验证结果 + 回归测试结果，缺一不算完成。</li></ol><h3 id="前置条件-6" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-6" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>测试框架能承载这类用例：它本身就是故障触发器（可能需要测试专用 Hint 或注入点）。</li><li>复现步骤可脚本化、可重复，不是「人手点一遍」。</li><li>评审流程认这套证据（把复现用例 + 前后对照结果作为合并的硬性材料）。</li></ul><h3 id="适用边界-6" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-6" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：能确定触发条件的缺陷修复，尤其并发/时序类。</li><li>不适用：无法在测试环境重放的偶发问题——此时门禁要退化为观测证据加灰度监控，而不是硬套复现用例。</li><li>边界提醒：挂调试/注入会改变时序，回归结论要单独跑一遍正常路径。</li></ul><h3 id="反例与失败模式-6" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-6" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>把没复现当通过：故障本来低概率，没触发不等于修好了。</li><li>只交代码不交复现用例：评审退化成人工重走一遍排查，等于回到原点。</li><li>只对照不复现：修复前后要在相同条件下跑，才能排除这次恰好没触发。</li></ul><h3 id="可验证的效果指标-6" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-6" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>进入评审的修复中<strong>带稳定复现用例</strong>的比例（原文内部数据：超过 70%）。</li><li>修复后回滚/二次修复率（门禁有效的直接体现）。</li><li>复现用例对原始故障的覆盖率（研发评审第一步就要核对这项）。</li></ul><h3 id="原文短引用-6" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-6" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 2.4 节 — 以稳定复现作为修复交付门禁</a></p><p>「稳定复现用例是修复进入代码评审的必要条件。」</p><p>「这个用例在修复前必须能触发原来的问题，修复后必须能正常通过。只有完成这组验证，并通过完整的回归测试，代码才能进入评审。」</p><p>「研发先检查复现用例，对照原始问题确认其覆盖目标故障，再审查代码修改。审查通过后，按既有流程合并。」</p></blockquote><hr><h2 id="卡-8-把-loop-放进云端沙箱常驻" tabindex="-1">卡 8：把 Loop 放进云端沙箱常驻 <a class="header-anchor" href="#卡-8-把-loop-放进云端沙箱常驻" aria-label="Permalink to &quot;卡 8：把 Loop 放进云端沙箱常驻&quot;">​</a></h2><h3 id="要解决的问题-7" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-7" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>Agent 跑在每个研发本机上，状态不能复用、权限散在个人账号、无法 7×24 接告警；本机被 Agent 搞坏，损失的是自己的开发环境。</p><h3 id="具体做法-7" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-7" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ul><li><strong>云端承载</strong>：把 Agent 和任务流程放到云端沙箱，持续处理告警、推进修复。</li><li><strong>环境隔离</strong>：Agent 的运行环境与研发本地电脑隔离，沙箱被破坏也不影响本地开发环境。</li><li><strong>权限最小化</strong>：只授予完成任务所需的权限，限制它能访问和操作的范围。</li><li><strong>团队共用</strong>：成员共用同一套云端环境，协同配置和完善工具与流程（环境是团队资产，不是某人的私产）。</li><li><strong>产出可复查</strong>：分析记录与报告上传展示平台，供事后查阅。</li></ul><h3 id="前置条件-7" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-7" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>一个能被程序化创建/销毁的执行环境（容器、临时云主机、Codespaces 类服务）。</li><li>告警能以 API/webhook 形式投递到该环境。</li><li>权限模型设计：按任务类型授最小权限，凭据可轮换、可吊销。</li></ul><h3 id="适用边界-7" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-7" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>适用：需要长期待命的场景——值班、告警响应、定时巡检。</li><li>不适用：所有动作必须由本人在本地发起才合规的场景（金融/政务的强留痕环境）。</li><li>注意：常驻意味着风险常驻，隔离与最小权限不是可选项。</li></ul><h3 id="反例与失败模式-7" tabindex="-1">反例与失败模式 <a class="header-anchor" href="#反例与失败模式-7" aria-label="Permalink to &quot;反例与失败模式&quot;">​</a></h3><ul><li>为了上云而上云：每人各装一套环境，成本和漂移双爆。</li><li>沙箱权限给成管理员：出问题回滚比本机还难。</li><li>没有可观测面板：不知道它在处理什么、卡在哪一步。</li></ul><h3 id="可验证的效果指标-7" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-7" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>累计处理告警数 / 累计完成修复数（原文内部数据：半年内从上万次报警识别并记录两百多个缺陷）。</li><li>单条告警端到端时长（接收 → 复现 → 修复提交）。</li><li>沙箱环境的复用率与故障隔离次数（隔离机制是否真的生效过）。</li></ul><h3 id="原文短引用-7" tabindex="-1">原文短引用 <a class="header-anchor" href="#原文短引用-7" aria-label="Permalink to &quot;原文短引用&quot;">​</a></h3><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 第三节 — 云端运行与实践效果</a></p><p>「为支持 7×24 小时持续处理报警和推进修复，我们基于云端沙箱构建了 PolarDB-X Agent，承载上述流程的持续运行。」</p><p>「云端沙箱还提供了两方面的安全保障：一是环境隔离，将 Agent 的运行环境与研发的本地电脑隔离，即使沙箱环境被破坏，也不会影响本地开发环境；二是权限最小化，只授予 Agent 完成任务所需的权限，限制它能够访问和操作的范围。」</p><p>「在本文所述的半年实践中，所有报警先由 Agent 完成首轮处理和分析。团队从上万次报警中识别并记录了两百多个缺陷，其中超过 70% 可以稳定复现，并由 Agent 完成修复后进入代码评审。」</p></blockquote><hr><h2 id="哪些是阿里云主张-内部数据-哪些可以自己复现" tabindex="-1">哪些是阿里云主张 / 内部数据，哪些可以自己复现 <a class="header-anchor" href="#哪些是阿里云主张-内部数据-哪些可以自己复现" aria-label="Permalink to &quot;哪些是阿里云主张 / 内部数据，哪些可以自己复现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结论</th><th>性质</th><th>你能自己做什么</th></tr></thead><tbody><tr><td>稳定复现是缺陷修复里最重要的一步（团队主张）</td><td>团队主张（文中明确是「我们认为」）</td><td>直接当自家修复门禁，零成本</td></tr><tr><td>Agent 现场信息梳理优于人工</td><td>团队内部观察，无对照实验</td><td>自测：同一批告警人工 vs Agent 首轮，比对定位到根因的耗时与漏线索率</td></tr><tr><td>从接告警起步而非从接需求起步</td><td>团队主张 + 内部实践</td><td>任何有 webhook 的告警系统都能起步</td></tr><tr><td>约一周让 Agent 封装出内部 CLI</td><td>内部投入数据</td><td>同样可做，但成本取决于平台有没有可参考的实现</td></tr><tr><td>基于 JDI 重做调试 CLI、指定线程断点</td><td>工程做法（可复现）</td><td>换语言同理：debugpy/Delve/inspector 都能包成会话型 CLI</td></tr><tr><td>Heap Dump 集中加载 + 查询接口</td><td>工程做法（可复现）</td><td>用现成托管内存分析服务也行，不必自建</td></tr><tr><td>半年：上万次报警 → 200+ 缺陷 → &gt;70% 稳定复现</td><td><strong>内部数据，不可外推</strong></td><td>只能当量级参考，别拿去承诺自家 ROI</td></tr></tbody></table><hr><h2 id="一人公司-小团队的降级做法" tabindex="-1">一人公司 / 小团队的降级做法 <a class="header-anchor" href="#一人公司-小团队的降级做法" aria-label="Permalink to &quot;一人公司 / 小团队的降级做法&quot;">​</a></h2><p>原文给其他团队的路径是：从有明确验证方法的任务入手，所以小团队不必照抄全套。</p><table tabindex="0"><thead><tr><th>原做法</th><th>小团队降级版</th></tr></thead><tbody><tr><td>云端沙箱 7×24 常驻</td><td>本机定时任务或 CI 工作流跑 Agent（GitHub Actions、本地 cron 都行）；先做每天早上跑一遍告警摘要就够了</td></tr><tr><td>环境隔离 + 权限最小化</td><td>用一次性容器/Dev Container 跑 Agent，密钥放环境变量不落盘；给 Agent 只读凭据，写操作留给自己</td></tr><tr><td>结构化 CLI 封装 + 日志集中</td><td>先接托管服务自带的 API 与告警集成；日志用 Loki、Grafana Cloud 或对象存储加 grep，别自建日志平台</td></tr><tr><td>让 Agent 自行封装存量平台 CLI</td><td>用 Playwright 之类的浏览器自动化让 Agent 摸清接口后写脚本；脚本统一放仓库 <code>scripts/</code> 目录，纳入 code review</td></tr><tr><td>会话型调试 CLI + 指定线程断点</td><td>用现成可脚本化的调试器（Python 的 <code>debugpy</code>、<code>pdb</code>，Node 的 inspector 与 Chrome DevTools，Go 的 <code>dlv</code>），先用能在非交互模式下跑一条命令的工具</td></tr><tr><td>Heap Dump 集中化</td><td>直接用现成托管分析服务或本地大内存机器；Node 用 Chrome DevTools，Go 用 <code>pprof</code> 现成 UI，别自建平台</td></tr><tr><td>复现环境分级</td><td>只有一种：容器化测试环境 + 能钉版本/配置的 compose/Helm；临时实例就是「起一个用完就删」</td></tr><tr><td>稳定复现门禁</td><td>退回最小版本：修 bug 必须先有一个能失败的测试，修完转绿才能合。这是 CI 能自动卡的硬门禁</td></tr><tr><td>诊断 Skills</td><td>一个 <code>AGENTS.md</code> 或 <code>docs/agent/runbook.md</code>，写清这类问题按哪几步查、每步用哪条命令</td></tr><tr><td>上万次告警的规模</td><td>一个人没有告警洪峰，先从每周复盘一次线上小事故开始，把复现用例攒成回归集</td></tr></tbody></table><blockquote><p>提醒：卡 7 的门禁在一人公司尤其值得抄——它是唯一一条不需要基建投入、当天就能加上的硬约束。</p></blockquote><hr><h2 id="与现有页面的重叠与建议插入位置" tabindex="-1">与现有页面的重叠与建议插入位置 <a class="header-anchor" href="#与现有页面的重叠与建议插入位置" aria-label="Permalink to &quot;与现有页面的重叠与建议插入位置&quot;">​</a></h2><h3 id="现状-已核对-learn-ai-仓库" tabindex="-1">现状（已核对 learn-ai 仓库） <a class="header-anchor" href="#现状-已核对-learn-ai-仓库" aria-label="Permalink to &quot;现状（已核对 learn-ai 仓库）&quot;">​</a></h3><ul><li><code>docs/zh/practice/</code> 目前只有三篇：<code>index.md</code>（栏目页）、<code>reporter.md</code>（Vibe Coding 深度研究报告，navOrder 10）、<code>procurement-plan.md</code>（采购与实施方案，navOrder 20）。<strong>没有工程实践类页面</strong>，本页是填补。</li><li><code>docs/practice/ai-efficiency-practice.md</code>（英文站团队提效页）已覆盖 AI 覆盖研发全链路、每个环节设人工审核点。</li></ul><h3 id="重叠与差异" tabindex="-1">重叠与差异 <a class="header-anchor" href="#重叠与差异" aria-label="Permalink to &quot;重叠与差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>现有 <code>ai-efficiency-practice</code></th><th>本页</th></tr></thead><tbody><tr><td>主张面</td><td>AI 覆盖需求到测试全链路，每个输出环节设人工审核点</td><td>从告警到评审的端到端 Loop，人只做最终审查</td></tr><tr><td>机制深度</td><td>说「要审核」，没讲审核什么</td><td>审核对象是<strong>复现用例</strong>：修复前触发、修复后通过</td></tr><tr><td>数据</td><td>整体研发效率提升 40%+ 是外部案例团队数据</td><td>上万次告警、两百多个缺陷、超过 70% 稳定复现是阿里云内部半年数据，两者不可混用</td></tr><tr><td>失败模式</td><td>未展开</td><td>明确写出静态推演偏差、没复现当通过等失败模式</td></tr></tbody></table><h3 id="建议插入位置" tabindex="-1">建议插入位置 <a class="header-anchor" href="#建议插入位置" aria-label="Permalink to &quot;建议插入位置&quot;">​</a></h3><ol><li>新增文件 <code>docs/zh/practice/agent-incident-loop.md</code>（即本页草稿），frontmatter <code>navOrder: 30</code>，接在 <code>procurement-plan</code> 之后；同步把 <code>procurement-plan.md</code> 的 <code>next: false</code> 改为指向本页（该目录三篇都用显式 prev/next 串联）。</li><li><code>docs/zh/practice/index.md</code> 的按决策顺序读部分补一节 <code>### 3. 再看工程落地</code>，加一行链接，与现有两节平级。</li><li>栏目页那句定位目前停在先判断值不值得、风险在哪，再写采购和规矩；本页正好补上怎么落地这一环，可考虑在 index 结论里加半句指向。</li><li>与英文站互链：可在 <code>docs/practice/ai-efficiency-practice.md</code> 末尾加一句指向本页的链接（文案例如：工程机制细节见中文站 Loop 工程实践），反向在本站留一条英文页链接。</li><li>主题相关页（非重复，可互链）：<code>/zh/tech/06-agent-systems/skills</code>（Skills 机制）、<code>/zh/tech/06-agent-systems/workflow</code>（工作流编排）、<code>/zh/tech/06-agent-systems/recovery-hitl</code>（人在环与恢复）。</li></ol><hr><h2 id="一页速查-loop-的三条工程经验" tabindex="-1">一页速查：Loop 的三条工程经验 <a class="header-anchor" href="#一页速查-loop-的三条工程经验" aria-label="Permalink to &quot;一页速查：Loop 的三条工程经验&quot;">​</a></h2><p>原文最后收敛成三条，可当作自检清单——三条缺一条，Loop 就退化成聊天机器人：</p><ol><li><strong>让研发系统可以被 Agent 调用</strong>：把日志等现场材料集中管理，通过 CLI 或接口提供常用查询能力，并把诊断方法、工具说明和排查经验整理成 Skills，让 Agent 能够按需获取信息，沿着线索继续分析。</li><li><strong>让研发过程可以验证</strong>：提供复现环境、调试和内存分析工具，让 Agent 自行检验假设，再将稳定复现的过程固化为测试用例，通过修复前后的对照验证和回归测试检查修改效果。</li><li><strong>让任务能够持续运行</strong>：将 Agent 和任务流程放到云端，支持 7×24 小时持续处理报警、推进修复，并通过环境隔离和最小权限控制访问与操作范围。</li></ol><blockquote><p>原文链接：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E6%8A%A5%E8%AD%A6%E5%88%B0%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%EF%BC%8CPolarDB-X%20%E7%9A%84%20Loop%20%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">第 25 章 · 第四节 — 面向其他团队的实践建议</a></p><p>「Loop 的关键是让 Agent 根据运行结果修正分析、自主推进，并交付可复查的结果。」</p></blockquote>',162)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
